+def test_dict_setitem_delitem() -> None:
+    d = tvm_ffi.Dict({"a": 1})
+    d["b"] = 2
+    assert len(d) == 2
+    assert d["b"] == 2
+    del d["a"]
+    assert len(d) == 1
+    assert "a" not in d
+    with pytest.raises(KeyError):
